// Content Discovery - RSS Feeds
const feeds = [
  'https://techcrunch.com/category/artificial-intelligence/feed/',
  'https://venturebeat.com/ai/feed/',
  'https://openai.com/blog/rss.xml',
  'https://www.technologyreview.com/topicai/feed/',
  'https://ai.googleblog.com/feeds/posts/default'
];

const articles = [];
const maxPerFeed = 3;

// Simple RSS parsing (you'd use a proper RSS parser in real implementation)
for (const feedUrl of feeds) {
  try {
    const response = await $http.request({
      method: 'GET',
      url: feedUrl,
      headers: {
        'User-Agent': 'EII Discovery Bot 1.0'
      }
    });

    // Mock parsing - in real implementation, parse RSS XML
    // For now, just create sample articles
    articles.push({
      title: `AI Article from ${feedUrl.split('/')[2]}`,
      url: `https://example.com/ai-article-${Date.now()}`,
      source: feedUrl.split('/')[2],
      relevance: 0.8
    });

  } catch (error) {
    console.log(`Failed to fetch ${feedUrl}:`, error);
  }
}

// Filter for high relevance articles
const highRelevanceArticles = articles.filter(a => a.relevance >= 0.5);

return highRelevanceArticles.map(article => ({ json: article }));

// Generate Discovery Summary Report
const results = $input.all();
const timestamp = new Date().toISOString();

const summary = {
  discovery_run: timestamp,
  total_articles_found: results.length,
  successful_analyses: results.filter(r => r.json.success).length,
  failed_analyses: results.filter(r => !r.json.success).length,
  avg_eii_score: 0,
  top_articles: []
};

// Calculate average EII score
const successfulResults = results.filter(r => r.json.success && r.json.data);
if (successfulResults.length > 0) {
  const eiiScores = successfulResults.map(r => r.json.data.eii_score || 0);
  summary.avg_eii_score = eiiScores.reduce((a, b) => a + b, 0) / eiiScores.length;

  // Get top 3 highest EII scores
  summary.top_articles = successfulResults
    .sort((a, b) => (b.json.data.eii_score || 0) - (a.json.data.eii_score || 0))
    .slice(0, 3)
    .map(r => ({
      title: r.json.data.title || 'Unknown',
      url: r.json.data.url,
      eii_score: r.json.data.eii_score
    }));
}

console.log('📊 Discovery Summary:', JSON.stringify(summary, null, 2));

return [{ json: summary }];

